package com.loanops.fincompass.opportunity;
import com.loanops.fincompass.twin.FinancialTwinStore;import com.loanops.personal.canonical.PersonalFinanceCipher;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.transaction.support.TransactionTemplate;import org.springframework.transaction.PlatformTransactionManager;import java.sql.Timestamp;import java.time.*;import java.util.*;import static com.loanops.fincompass.opportunity.OpportunityModels.*;
public final class OpportunityStore {private final JdbcTemplate jdbc;private final PersonalFinanceCipher cipher;private final FinancialTwinStore twins;private final TransactionTemplate tx;public OpportunityStore(JdbcTemplate jdbc,PersonalFinanceCipher cipher,FinancialTwinStore twins,PlatformTransactionManager manager){this.jdbc=jdbc;this.cipher=cipher;this.twins=twins;this.tx=new TransactionTemplate(manager);}
 public Event save(String owner,Draft draft,Policy policy,Instant now){return tx.execute(s->{var snapshot=twins.get(owner,draft.financialSnapshotId());String key=cipher.contentHash(Map.of("type",draft.type().name(),"snapshot",draft.financialSnapshotId().toString(),"scenario",String.valueOf(draft.scenarioId()),"match",String.valueOf(draft.productMatchRunId()),"evidence",draft.evidence(),"version",policy.ruleVersion()));var rows=jdbc.query("SELECT id,payload_ciphertext FROM loanops.opportunity_event WHERE financial_user_id=? AND event_key=?",(r,n)->decode(r.getObject(1,UUID.class),r.getString(2)),snapshot.financialUserId(),key);if(!rows.isEmpty())return rows.getFirst();UUID id=UUID.randomUUID();Event event=new Event(id,draft.type(),now,draft.financialSnapshotId(),draft.scenarioId(),draft.productMatchRunId(),policy.ruleVersion(),"ACTIVE",draft.evidence(),draft.warnings());jdbc.update("INSERT INTO loanops.opportunity_event(id,financial_user_id,financial_snapshot_id,scenario_id,product_match_run_id,type,detected_at,rule_version,status,event_key,payload_ciphertext) VALUES (?,?,?,?,?,?,?,?,?,?,?)",id,snapshot.financialUserId(),draft.financialSnapshotId(),draft.scenarioId(),draft.productMatchRunId(),draft.type().name(),Timestamp.from(now),policy.ruleVersion(),"ACTIVE",key,cipher.seal("opportunity:"+id,event));return event;});}
 public List<Event> active(String owner){return jdbc.query("SELECT e.id,e.payload_ciphertext FROM loanops.opportunity_event e JOIN loanops.financial_users u ON u.id=e.financial_user_id WHERE u.owner_ref=? AND e.status='ACTIVE' ORDER BY e.detected_at,e.id",(r,n)->decode(r.getObject(1,UUID.class),r.getString(2)),owner);}
 private Event decode(UUID id,String payload){return cipher.open("opportunity:"+id,payload,Event.class);}}
